import numpy as np


def message_step(A, X, self_loops):
    A = np.asarray(A, dtype=float)
    if self_loops:
        A = A + np.eye(len(A))
    P = A / A.sum(axis=1, keepdims=True)
    return P @ np.asarray(X, dtype=float)


def k_steps(A, X, k):
    for _ in range(k):
        X = message_step(A, X, False)
    return np.asarray(X, dtype=float)

